// Receives the "registration.created" payload from events.theaugustdispatch.com
// (documented in the site repo at docs/n8n-webhooks.md) and builds the email.
const SECRET = 'SET_IN_N8N';
const input = $input.first().json;
if ((input.headers || {})['x-webhook-secret'] !== SECRET) return [];

const p = input.body || {};
if (p.event_type !== 'registration.created' || !p.registration) return [];

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const r = p.registration, pay = p.payment, ev = p.event, ch = p.channels || {};

const idea = r.ai_idea
  ? `<tr><td style="padding:0 32px 8px">
       <div style="border:1px solid #F5C518;border-radius:12px;padding:20px;background:#13263A">
         <div style="font:700 11px 'Courier New',monospace;letter-spacing:2px;text-transform:uppercase;color:#F5C518">An idea for your website</div>
         <div style="margin-top:10px;font:16px/1.6 Arial,sans-serif;color:#ffffff">${esc(r.ai_idea)}</div>
       </div></td></tr>`
  : '';

const step = (n, label, value) => `<tr>
  <td width="44" valign="top" style="padding:8px 0"><div style="width:30px;height:30px;border-radius:15px;background:#F5C518;color:#0D1B2A;font:700 14px/30px 'Courier New',monospace;text-align:center">${n}</div></td>
  <td style="padding:8px 0"><div style="font:700 11px 'Courier New',monospace;letter-spacing:2px;text-transform:uppercase;color:#F5C518">${esc(label)}</div>
  <div style="font:700 19px/1.3 Arial,sans-serif;color:#ffffff;margin-top:2px">${esc(value)}</div></td></tr>`;

// The person's own share card, when the site sends one.
const share = p.share?.url
  ? `<tr><td style="padding:28px 32px 0;font:800 20px Arial,sans-serif;color:#ffffff">Tell your network</td></tr>
  <tr><td style="padding:8px 32px 0;font:16px/1.6 Arial,sans-serif;color:#EEF2F6">This card is yours. Share it and bring a friend along.</td></tr>
  <tr><td style="padding:16px 32px 0"><a href="${esc(p.share.url)}"><img src="${esc(p.share.card_wide_url)}" width="536" alt="${esc(r.first_name)} is building at ${esc(ev.name)}" style="display:block;width:100%;max-width:536px;height:auto;border:0;border-radius:12px"></a></td></tr>
  <tr><td style="padding:16px 32px 0"><a href="${esc(p.share.url)}" style="display:inline-block;background:#F5C518;border-radius:999px;padding:12px 24px;font:800 16px Arial,sans-serif;color:#0D1B2A;text-decoration:none">Open and share your card</a></td></tr>`
  : '';

const html = `<div style="background:#EEF2F6;padding:24px 12px">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;margin:0 auto;background:#0D1B2A;border-radius:16px;overflow:hidden">
  <tr><td style="padding:14px 32px;border-bottom:3px solid #F5C518;font:700 13px 'Courier New',monospace;letter-spacing:1.5px;color:#F5C518">${esc(ev.edition)}</td></tr>
  <tr><td style="padding:32px 32px 8px">
    <div style="font:800 30px/1.15 Arial,sans-serif;color:#ffffff">Thank you, ${esc(r.first_name)}. One step left.</div>
    <div style="margin-top:14px;font:16px/1.6 Arial,sans-serif;color:#EEF2F6">You are registered for ${esc(ev.name)}: ${esc(ev.dates_label)}, at ${esc(ev.venue_name)}, ${esc(ev.venue_address)}.</div>
  </td></tr>
  <tr><td style="height:16px"></td></tr>
  ${idea}
  <tr><td style="padding:24px 32px 0;font:800 20px Arial,sans-serif;color:#ffffff">Pay to confirm your seat</td></tr>
  <tr><td style="padding:8px 32px 0"><table role="presentation" cellpadding="0" cellspacing="0" width="100%">
    ${step(1, `Send ${pay.amountLabel} by ${pay.method}`, pay.number)}
    ${step(2, 'Account name', pay.accountName)}
    ${step(3, 'Reference', pay.reference)}
  </table></td></tr>
  <tr><td style="padding:20px 32px 0"><div style="background:#F5C518;border-radius:12px;padding:16px 20px;font:800 17px/1.4 Arial,sans-serif;color:#0D1B2A">${esc(pay.confirmationNote)}</div></td></tr>
  ${share}
  <tr><td style="padding:18px 32px 32px;font:14px/1.6 Arial,sans-serif;color:#B9C5D3">${esc(pay.refundPolicy)} Questions? WhatsApp ${esc(ev.contact_whatsapp)} or email <a href="mailto:${esc(ev.contact_email)}" style="color:#F5C518">${esc(ev.contact_email)}</a>.</td></tr>
</table></div>`;

return [{
  json: {
    to: ch.email?.to || r.email,
    emailEnabled: ch.email?.enabled !== false,
    whatsappEnabled: ch.whatsapp?.enabled === true,
    whatsappTo: ch.whatsapp?.to || r.whatsapp,
    subject: `You're registered for ${ev.name}. One step left.`,
    replyTo: ev.contact_email,
    html,
    registrationId: r.id,
    firstName: r.first_name,
  },
}];
